import { type } from "arkenv";

try {
  const t = type("string.ip | 'localhost'");
  console.log("Successfully created type:", t.expression);
  console.log("valid 127.0.0.1:", t("127.0.0.1"));
  console.log("valid localhost:", t("localhost"));
  console.log("invalid 999.999.999.999:", t("999.999.999.999"));
} catch (e) {
  console.error("Error:", e);
}

import { type } from "arkenv";

try {
  const t = type("1 <= number.integer <= 65535");
